mapper.select:
SELECT id, user_id, session_id, action_type, target_order_id, assistant_message_id,
       status, expire_time, result_message, create_time, update_time
FROM ai_chat_pending_action
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
  AND status = 1
  AND expire_time > #{now}
  AND assistant_message_id IS NOT NULL
ORDER BY id DESC
LIMIT 1

SELECT id, user_id, session_id, action_type, target_order_id, assistant_message_id, status,
       expire_time, result_message, create_time, update_time
FROM ai_chat_pending_action
WHERE id = #{actionId}
  AND user_id = #{userId}

SELECT id, user_id, session_id, action_type, target_order_id, assistant_message_id, status,
       expire_time, result_message, create_time, update_time
FROM ai_chat_pending_action
WHERE id = #{actionId}
  AND user_id = #{userId}
FOR UPDATE

mapper.update:
UPDATE ai_chat_pending_action
SET status = 5,
    result_message = #{resultMessage},
    update_time = #{updateTime}
WHERE session_id = #{sessionId}
  AND user_id = #{userId}
  AND status = 1

UPDATE ai_chat_pending_action
SET status = #{newStatus},
    result_message = #{resultMessage},
    update_time = #{updateTime}
WHERE id = #{actionId}
  AND user_id = #{userId}
  AND status = 1
